 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, SRGBColorSpace, ClampToEdgeWrapping } = THREE;

  const group = new Group();
  const timelines = [];

  const atlasRect = { x: 0, y: 0, w: 512, h: 320 };
  const aspect = atlasRect.w / atlasRect.h;
  const height = 1.2;
  const width = height * aspect;

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide,
  });

  const mesh = new Mesh(geometry, material);
  mesh.rotation.set(0, 0, 0);
  group.add(mesh);

  mesh.onBeforeRender = (renderer, scene, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };

  const url = config.imageUrl;
  if (url) {
    ctx.textureLoader.loadTexture(url).then((tex) => {
      if (!tex || !tex.isTexture) return;

      tex.colorSpace = SRGBColorSpace;
      tex.wrapS = ClampToEdgeWrapping;
      tex.wrapT = ClampToEdgeWrapping;

      const imgW = tex.image.width || atlasRect.w;
      const imgH = tex.image.height || atlasRect.h;

      const repeatX = atlasRect.w / imgW;
      const repeatY = atlasRect.h / imgH;
      const offsetX = atlasRect.x / imgW;
      const offsetY = 1 - (atlasRect.y + atlasRect.h) / imgH;

      tex.repeat.set(repeatX, repeatY);
      tex.offset.set(offsetX, offsetY);
      tex.updateMatrix();

      material.map = texture(tex);
      material.needsUpdate = true;
    }).catch(() => {});
  }

  group.userData = {
    handlers: {},
    cleanup: () => {
      mesh.onBeforeRender = null;
      timelines.forEach((tl) => tl.kill());
      geometry.dispose();
      material.dispose();
    },
  };

  return group;
}
